/// The arm for `name`, if it is a canonical dotted `host.*` verb.
pub fn lookup(name: &str) -> Option<Arm> {
    DISPATCH_TABLE
        .binary_search_by(|(verb, _)| (*verb).cmp(name))
        .ok()
        .map(|i| DISPATCH_TABLE[i].1)
}

/// The verb names, in table order.
pub fn names() -> Vec<&'static str> {
    DISPATCH_TABLE.iter().map(|(verb, _)| *verb).collect()
}
